def parse_duration(text):
    text = text.strip().lower()
    if not text:
        return -1
    if text.isdigit():
        return int(text) * 60
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    total = 0
    num = ""
    for ch in text:
        if ch.isdigit():
            num += ch
        elif ch in units and num:
            total += int(num) * units[ch]
            num = ""
        else:
            return -1
    if num:
        return -1
    return total

